            score -= 8.0 / (1 + dop)
        else:
            score += 0.5 / (1 + dop)

        # Encourage moving while not giving up direct path
        if best_res != center:
            cur_dir = (1 if best_res[0] > sx else -1 if best_res[0] < sx else 0,
